import re
from datetime import datetime

_DIGITS = "0123456789"
_GMAIL = {"gmail.com", "googlemail.com"}
_EXT_RE = re.compile(r"x|ext|#", re.IGNORECASE)
_ZIP4_RE = re.compile(r"^([0-9]{5})-[0-9]{4}$")
_DATE_FORMATS = ("%Y-%m-%dT%H:%M:%S", "%Y-%m-%d", "%m/%d/%Y")


def dedupe_contacts(rows):
    def get(row, key):
        v = row.get(key, "")
        return "" if v is None else str(v)

    def norm_email(raw):
        s = raw
        m = re.search(r"<([^<>]*)>", s)
        if m:
            s = m.group(1)
        s = s.strip().lower()
        if s.count("@") == 1:
            local, domain = s.split("@")
            if domain in _GMAIL:
                local = local.split("+")[0].replace(".", "")
                domain = "gmail.com"
            s = local + "@" + domain
        return s

    def email_valid(s):
        if s.count("@") != 1:
            return False
        local, domain = s.split("@")
        return bool(local) and "." in domain and not domain.startswith(".") and not domain.endswith(".")

    def norm_phone(raw):
        m = _EXT_RE.search(raw)
        if m:
            raw = raw[:m.start()]
        d = "".join(c for c in raw if c in _DIGITS)
        if len(d) == 11 and d[0] == "1":
            d = d[1:]
        if len(d) == 10 and d[0] not in "01":
            return d
        return ""

    def norm_zip(raw):
        z = raw.strip()
        m = _ZIP4_RE.match(z)
        if m:
            z = m.group(1)
        if len(z) == 4 and all(c in _DIGITS for c in z):
            z = "0" + z
        if len(z) == 5 and all(c in _DIGITS for c in z):
            return z
        return ""

    def norm_name(raw):
        n = raw.strip()
        if n.isupper() or n.islower():
            n = n.title()
        return n

    def parse_date(raw):
        s = raw.strip()
        for fmt in _DATE_FORMATS:
            try:
                return datetime.strptime(s, fmt)
            except ValueError:
                continue
        raise ValueError("Unrecognized date format: %r" % raw)

    # Normalize rows, dropping those with no valid email or phone.
    recs = []
    for idx, row in enumerate(rows):
        e = norm_email(get(row, "email"))
        email = e if email_valid(e) else ""
        phone = norm_phone(get(row, "phone"))
        if not email and not phone:
            continue
        source = get(row, "source").strip().lower()
        tags = set()
        for t in re.split(r"[;,]", get(row, "tags")):
            t = t.strip().lower()
            if t:
                tags.add(t)
        recs.append({
            "idx": idx,
            "email": email,
            "phone": phone,
            "first_name": norm_name(get(row, "first_name")),
            "last_name": norm_name(get(row, "last_name")),
            "zip": norm_zip(get(row, "zip")),
            "source": source,
            "manual": source == "manual",
            "tags": tags,
            "opted_out": get(row, "opted_out").strip().lower() in ("y", "yes", "true", "1"),
            "updated": parse_date(get(row, "updated")),
        })

    # Union-find over the kept records.
    parent = list(range(len(recs)))

    def find(i):
        while parent[i] != i:
            parent[i] = parent[parent[i]]
            i = parent[i]
        return i

    def union(a, b):
        ra, rb = find(a), find(b)
        if ra != rb:
            if ra < rb:
                parent[rb] = ra
            else:
                parent[ra] = rb

    by_email = {}
    by_phone_last = {}
    for i, r in enumerate(recs):
        if r["email"]:
            if r["email"] in by_email:
                union(i, by_email[r["email"]])
            else:
                by_email[r["email"]] = i
        last_key = r["last_name"].lower()
        if r["phone"] and last_key:
            k = (r["phone"], last_key)
            if k in by_phone_last:
                union(i, by_phone_last[k])
            else:
                by_phone_last[k] = i

    groups = {}
    for i in range(len(recs)):
        groups.setdefault(find(i), []).append(i)

    epoch = datetime.min

    def pick(members, field):
        best = None
        best_key = None
        for i in members:
            r = recs[i]
            if not r[field]:
                continue
            key = (0 if r["manual"] else 1,
                   -(r["updated"] - epoch).total_seconds(),
                   r["idx"])
            if best_key is None or key < best_key:
                best_key = key
                best = r[field]
        return best if best is not None else ""

    # Order groups by earliest input row (members are in input order).
    ordered = sorted(groups.values(), key=lambda m: recs[m[0]]["idx"])

    result = []
    for members in ordered:
        tags = set()
        for i in members:
            tags |= recs[i]["tags"]
        latest = max(recs[i]["updated"] for i in members)
        result.append({
            "first_name": pick(members, "first_name"),
            "last_name": pick(members, "last_name"),
            "zip": pick(members, "zip"),
            "email": pick(members, "email"),
            "phone": pick(members, "phone"),
            "source": pick(members, "source"),
            "tags": ";".join(sorted(tags)),
            "opted_out": "Y" if any(recs[i]["opted_out"] for i in members) else "N",
            "updated": "%04d-%02d-%02d" % (latest.year, latest.month, latest.day),
        })
    return result
```

Notes:

- **Opt-outs:** The function doesn't remove opted-out people. It returns them with `opted_out == "Y"` (set if any duplicate row opted out). Before sending, filter with `[p for p in dedupe_contacts(rows) if p["opted_out"] == "N" and p["email"]]`. People with no valid email can't receive the email anyway.
- **ZIP+4:** I read "looks like ZIP+4" literally as 5 digits, a hyphen, then 4 digits. Something like `2139-4307` (Excel-eaten zero plus a +4) becomes `""`. If you want that case rescued to `02139`, loosen the regex to `[0-9]{4,5}-[0-9]{4}`.
- **Bad dates:** An `updated` value in an unexpected format raises `ValueError` rather than being silently guessed. That is deliberate, so a bad export gets caught before the send.
